author.hbs:
{{!< default}}

{{#author}}
<header class="home-hero" style="padding-bottom:20px">
  <div class="wrap">
    <div class="author-box" style="margin-top:0">
      {{#if profile_image}}<img src="{{img_url profile_image size="m"}}" alt="{{name}}">{{/if}}
      <div>
        <div class="eyebrow">Auteur</div>
        <h1 style="font-size:40px;margin:6px 0">{{name}}</h1>
        {{#if bio}}<p class="ab" style="max-width:56ch">{{bio}}</p>{{/if}}
      </div>
    </div>
  </div>
</header>
{{/author}}

<section class="blk" style="padding-top:30px">
  <div class="wrap">
    <ul class="postfeed">
      {{#foreach posts}}
        {{> "post-card"}}
      {{/foreach}}
    </ul>
    {{pagination}}
  </div>
</section>

page.hbs:
{{!< default}}

{{#post}}
<article class="article {{post_class}}">
  {{#if @page.show_title_and_feature_image}}
  <div class="wrap">
    <header class="article-head">
      <h1>{{title}}</h1>
      {{#if custom_excerpt}}<p class="article-excerpt">{{custom_excerpt}}</p>{{/if}}
    </header>
  </div>

  {{#if feature_image}}
    <figure class="feature-image">
      <img src="{{img_url feature_image size="xl"}}" alt="{{#if feature_image_alt}}{{feature_image_alt}}{{else}}{{title}}{{/if}}">
    </figure>
  {{/if}}
  {{/if}}

  <div class="wrap">
    <section class="article-body gh-content">
      {{content}}
    </section>
  </div>
</article>

{{!-- Dedicated /subscribe landing gets the capture block --}}
{{#has slug="subscribe"}}{{> "subscribe"}}{{/has}}
{{/post}}

